window.__GUIDE_CHUNKS__.push([{"id": "01-001", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 1, "title": "Buckle up, front seat and back seat", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. Two seconds per ride.", "plain": "Buckle up in every seat, every ride. Belted front-seat car occupants are 45% less likely to be killed in a crash; in light trucks, 60% less. In 2022, 50% of US passenger-vehicle deaths with known belt status were unbelted, and 60% of rear-seat deaths were unbelted.", "benefit_text": "NHTSA estimates seatbelts cut fatal-injury risk 45% for front-seat car occupants and 60% for light-truck front occupants. In 2022, 50% of US passenger-vehicle deaths with known belt status were unbelted; 60% of rear-seat deaths were unbelted. WHO's figure: up to 50% lower death risk for vehicle occupants.", "sources": "NHTSA (2024). Occupant Protection in Passenger Vehicles: 2022 Data (DOT HS 813 573). <https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813573>; WHO (2025). Road traffic injuries fact sheet. <https://www.who.int/news-room/fact-sheets/detail/road-traffic-injuries>", "notes": "**Ontario law:** Highway Traffic Act s.106 requires every driver and passenger to wear a seatbelt, and drivers must make sure passengers under 16 are buckled. Fines and demerit points apply. The 45% and 60% figures are NHTSA estimates from crash databases, not randomized trials.", "urls": ["https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813573", "https://www.who.int/news-room/fact-sheets/detail/road-traffic-injuries"]}, {"id": "01-002", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 2, "title": "Wear a helmet on a motorcycle or e-bike, and fasten the strap", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "A certified helmet costs roughly $20–$50. Five seconds to put on and fasten.", "plain": "Helmet plus a snug chin strap: motorcycle riders are about two-fifths less likely to die in a crash, with head injuries down about seven-tenths. A loose strap hanging off your head does not count. The same logic applies to e-bikes, where head injuries happen the same way.", "benefit_text": "Cochrane combined analysis: motorcycle riders wearing helmets had 42% lower death risk (OR 0.58, 95% CI 0.50–0.68) and 69% fewer head injuries (OR 0.31, 95% CI 0.25–0.38).", "sources": "Liu BC et al. (2008). Helmets for preventing injury in motorcycle riders. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD004333.pub3>", "notes": "**Ontario law:** HTA s.104(1) requires helmets on motorcycles; s.103.1(2) requires helmets on power-assisted bicycles (e-bikes). The data above come from motorcycles; e-bike numbers are inferred because crash head injuries occur the same way.", "urls": ["https://doi.org/10.1002/14651858.CD004333.pub3"]}, {"id": "01-003", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 3, "title": "Install smoke alarms; add a carbon monoxide alarm if you burn fuel or have an attached garage", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A smoke alarm is about $15–$30; a CO alarm about $30–$60. Test monthly, replace batteries yearly.", "plain": "A working smoke alarm cuts the chance of dying in a home fire by about three-fifths. In fatal US home fires, 41% of the time people were asleep — your nose will not wake you. Carbon monoxide has no smell — add a CO alarm if you heat with gas, oil, wood, propane, and add one for an attached garage.", "benefit_text": "Marshall et al. (1998): a working smoke detector was linked to about 60% lower death risk in residential fires (OR 0.39, 95% CI 0.18–0.83). USFA (2018–2020): 24% of fatal home fires had no smoke alarm, and in 41% people were asleep when the fire started.", "sources": "Marshall SW et al. (1998). Fatal residential fires: who dies and who survives? JAMA. <https://doi.org/10.1001/jama.279.20.1633>; USFA (2022). Fatal Fires in Residential Buildings (2018–2020). <https://www.usfa.fema.gov/downloads/pdf/statistics/v22i2.pdf>", "notes": "**Ontario law:** The Ontario Fire Code requires working smoke alarms on every storey and outside sleeping areas. Since January 1, 2026 (O. Reg. 87/25), homes with a fuel-burning appliance, fireplace, or attached garage need a CO alarm on every storey plus beside each sleeping area. <https://www.ajax.ca/en/new-ontario-carbon-monoxide-alarm-requirements-take-effect-january-1-2026.aspx> Graded B because the smoke-alarm evidence is a single case-control study, and there is no direct mortality trial of CO alarms — the CO recommendation follows from where and when CO deaths happen.", "urls": ["https://doi.org/10.1001/jama.279.20.1633", "https://www.ajax.ca/en/new-ontario-carbon-monoxide-alarm-requirements-take-effect-january-1-2026.aspx", "https://www.usfa.fema.gov/downloads/pdf/statistics/v22i2.pdf"]}, {"id": "01-004", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 4, "title": "Replace gas hoses and appliances on schedule; never DIY gas piping; refuse door-to-door \"mandatory\" sales", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A certified connector hose costs a few dollars; appliances last years. Check expiry dates when you replace anything.", "plain": "Gas connectors and appliances past their service life get replaced, not nursed along. Never modify gas piping and meters yourself. A salesperson at your door saying an upgrade is \"mandatory\" can be refused on the spot.", "benefit_text": "In Ontario only TSSA-certified technicians may install, alter, or service gas appliances and piping — uncertified gas work is illegal. Ontario's Consumer Protection Act s.43.1 (in force March 1, 2018) bans unsolicited door-to-door sales of furnaces, water heaters, and related services, so you may refuse or cancel such contracts. If you smell gas: touch no switches, leave the house, and call 911 from outside.", "sources": "TSSA, \"Safety is a Right, Not a Compromise\" — fuels professional verification and the CPA door-to-door sales ban (s.43.1, in force March 1, 2018, covering furnaces, water heaters, and related services). <https://www.tssa.org/sites/default/files/2023-10/FS-Professional-Verification-Checklist-Other-2022.pdf>", "notes": "**Ontario rule:** Gas work is a TSSA monopoly — hire a certified technician and keep the invoice. The door-to-door ban covers furnaces, air conditioners, water heaters, and water treatment devices sold at the door.", "urls": ["https://www.tssa.org/sites/default/files/2023-10/FS-Professional-Verification-Checklist-Other-2022.pdf"]}, {"id": "01-005", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 5, "title": "Don't pick, buy, or eat wild mushrooms — no folk test works", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. The hard part is giving up a seasonal foraging habit.", "plain": "No folk test works — not the silver needle, not \"bugs ate it so it's safe,\" not bright colours. In 2025, China CDC logged 828 mushroom-poisoning incidents: 2,165 people poisoned, 13 dead (0.6%). That year 34 previously unrecorded toxic species were identified.", "benefit_text": "China CDC 2025: 828 incidents across 27 provinces, 2,165 cases, 13 deaths (0.6% case fatality — the lowest in six years). 138 toxic species identified, 34 newly recorded in poisoning incidents. 2019–2024: 276–676 incidents per year, fatality 0.87%–2.86%.", "sources": "Mushroom Poisoning Outbreaks — China, 2025. China CDC Weekly (2026). <https://doi.org/10.46234/ccdcw2026.120>", "notes": "If someone ate the wrong one, call the Ontario Poison Centre at 1-844-764-7669 and go to the emergency department with the leftover mushrooms or a photo — identifying the species decides the treatment. \"Locals know which are safe\" fails because new toxic species keep being recorded.", "urls": ["https://doi.org/10.46234/ccdcw2026.120"]}, {"id": "01-006", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 6, "title": "Don't charge e-bikes in hallways, elevators, or at home overnight", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. The hard part is walking the extra metres to a safe charging spot every time.", "plain": "A lithium battery can go from fine to fully burning in under a minute, giving off highly toxic smoke. A fire in the hallway burns your only escape route. In 2021 China reported 18,000 e-bike fires with 65 deaths — 60 of them indoors.", "benefit_text": "China's 2021 figures: 18,000 e-bike fires, 65 dead, 222 injured; 3,782 fires in buildings caused 60 deaths and 175 injuries. After enforcement in 2024, fire counts fell 42.2% and casualties over 90%.", "sources": "Ministry of Emergency Management (China) (2023), reply on e-bike fire data. <https://www.mem.gov.cn/gk/jytabljggk/zxwytadfzy/2022zx/202301/t20230119_440918.shtml>", "notes": "**Canada:** Buy batteries and chargers certified to UL/CSA standards; never use damaged, modified, or off-brand packs; never charge overnight unattended; store and charge away from exits and check your landlord or condo rules.", "urls": ["https://www.mem.gov.cn/gk/jytabljggk/zxwytadfzy/2022zx/202301/t20230119_440918.shtml"]}, {"id": "01-007", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 7, "title": "Measure your blood pressure; if it's high, take medication to target", "money": "low", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "A home monitor is about $50–$100. Generic blood-pressure pills cost a few dollars a month with drug coverage. One minute per measurement. The hard part is taking pills with no symptoms.", "plain": "Every 10 mmHg lower systolic pressure means about a fifth fewer major cardiovascular events, about a quarter fewer strokes, about a quarter less heart failure, and about an eighth lower death. Measure first — most people with high blood pressure don't know it.", "benefit_text": "Meta-analysis of 123 trials (610,000+ people): per 10 mmHg lower systolic — major cardiovascular events RR 0.80, stroke RR 0.73, heart failure RR 0.72, total mortality RR 0.87.", "sources": "Ettehad D et al. (2016). Blood pressure lowering for prevention of cardiovascular disease and death. Lancet. <https://doi.org/10.1016/S0140-6736(15)01225-8>", "notes": "**Canada:** Measure at your pharmacy or family doctor — Hypertension Canada's general target is below 140/90 (below 130/80 with diabetes); your doctor sets your personal target. Generics are covered by ODB for seniors and social-assistance recipients and by most work plans.", "urls": ["https://doi.org/10.1016/S0140-6736(15"]}, {"id": "01-008", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 8, "title": "From your mid-30s, if overweight, get a fasting glucose test once — repeat every 3 years if normal", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "A lab test costs roughly $15–$30 without coverage; free with an OHIP-covered requisition from your doctor. One blood draw.", "plain": "One blood draw can catch prediabetes years before any symptoms. The US Preventive Services Task Force recommends screening adults 35–70 carrying extra weight, and repeating every 3 years if normal.", "benefit_text": "USPSTF (B recommendation): screen adults aged 35–70 with overweight (BMI ≥25) or obesity (BMI ≥30) for prediabetes and type 2 diabetes, even with no symptoms; \"screening every 3 years is reasonable\" if glucose is normal.", "sources": "US Preventive Services Task Force (2021). Screening for Prediabetes and Type 2 Diabetes. <https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/screening-for-prediabetes-and-type-2-diabetes>", "notes": "**Canada:** Diabetes Canada recommends screening from age 40 every 3 years, earlier or annually with risk factors — start with the CANRISK questionnaire and ask your family doctor for a lab requisition (OHIP-covered). Catching prediabetes early means lifestyle changes can often reverse it without drugs.", "urls": ["https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/screening-for-prediabetes-and-type-2-diabetes"]}, {"id": "01-009", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 9, "title": "Don't speed; don't drink and drive", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. Driving slower costs a few minutes per trip. The hard part is declining the drink at dinner.", "plain": "Each 1% higher average speed means about 4% more fatal crashes. There is no safe amount of alcohol for driving — risk starts rising at very low blood-alcohol levels.", "benefit_text": "WHO: 1% higher mean speed → 4% higher fatal-crash risk. Alcohol impairment risk rises from very low blood-alcohol concentrations, with no safe threshold identified.", "sources": "WHO (2025). Road traffic injuries fact sheet. <https://www.who.int/news-room/fact-sheets/detail/road-traffic-injuries>", "notes": "**Ontario law:** Impaired driving is a Criminal Code offence; provincial penalties start below the criminal threshold. Speeding and stunt driving carry fines, demerit points, and possible licence suspension and vehicle impoundment. Graded B because the speed figures are modelled, and WHO gives direction rather than numbers for alcohol.", "urls": ["https://www.who.int/news-room/fact-sheets/detail/road-traffic-injuries"]}, {"id": "01-010", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 10, "title": "Car seats are sized by weight and height, not age — never hold a child on your lap", "money": "high", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "$100–$400 per seat, usable for years. One extra minute to strap the child in.", "plain": "Car seats cut fatal-injury risk about 71% for infants under 1 and 54% for ages 1–4. But the legal cutoff isn't age — it's the child's weight and height (exact brackets in Notes below). A heavy preschooler may already need a booster; a light older child may still need the forward-facing seat. Holding a child on your lap does nothing — you cannot hold on in a crash.", "benefit_text": "NHTSA estimates: car seats cut fatal-injury risk 71% for infants under 1 and 54% for children 1–4 in cars. WHO's figure for infants: 71%.", "sources": "NHTSA (2024). Occupant Protection in Passenger Vehicles: 2022 Data (DOT HS 813 573). <https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813573>; WHO (2025). Road traffic injuries fact sheet. <https://www.who.int/news-room/fact-sheets/detail/road-traffic-injuries>; SickKids (aboutkidshealth.ca) — Ontario car-seat rules by weight and the five-step seatbelt test. <https://www.aboutkidshealth.ca/iu/healthaz/na/car-seat-safety-for-infants-and-children/>", "notes": "**Ontario:** HTA s.106 and O. Reg. 613 — rear-facing under 9 kg, forward-facing 9–18 kg, booster 18–36 kg until the child is 8 years old or 145 cm tall (whichever comes first); drivers are responsible for passengers under 16. **Quebec:** Highway Safety Code art. 397 — restraint adapted to the child's weight and size until 145 cm tall or 9 years old (the old 63 cm seated-height cutoff was replaced on 2019-04-18). Before dropping the booster entirely, do the five-step seatbelt test: back flat against the vehicle seat, knees bending at the seat edge, shoulder belt centred on the collarbone, lap belt low on the thighs, and the child stays put for the whole ride. Install exactly per the manual — a misinstalled seat is barely a seat. Under-1s ride rear-facing.", "urls": ["https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813573", "https://www.aboutkidshealth.ca/iu/healthaz/na/car-seat-safety-for-infants-and-children/", "https://www.who.int/news-room/fact-sheets/detail/road-traffic-injuries"]}, {"id": "01-011", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 11, "title": "If you have small children, fit window limiters — screens don't count", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Window limiters or child safety locks cost roughly $20–$50 per window. Ten minutes to install.", "plain": "In New York's \"Children Can't Fly\" program, free window guards plus education cut reported child falls 50% in one Bronx district over three years — then landlords were required to install them. A screen pushes straight out; it is not protection.", "benefit_text": "Spiegel & Lindaman (1977): reported falls in the Bronx fell 50% from 1973 to 1975; in 1976 New York City's health code began requiring landlords to provide window guards in apartments where children 10 and under live.", "sources": "Spiegel CN, Lindaman FC (1977). Children can't fly: a program to prevent childhood morbidity and mortality from window falls. American Journal of Public Health. <https://doi.org/10.2105/AJPH.67.12.1143>", "notes": "**Ontario:** In Toronto, rental apartment buildings must have window safety devices limiting openings to 100 mm or less. Keep beds, sofas, and boxes away from windows and balconies. Most US falls happened from the second storey or lower — this is not only a high-rise issue.", "urls": ["https://doi.org/10.2105/AJPH.67.12.1143"]}, {"id": "01-012", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 12, "title": "Eyes on children near water; lifejackets for boating and open-water swimming", "money": "low", "time": "mid", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "A lifejacket costs about $30–$80. The other cost is your undivided attention.", "plain": "Falling overboard in a lifejacket means roughly half the drowning risk of going in without one. Drowning remains the top killer of young children in China, with rural rates about double urban ones.", "benefit_text": "Cummings et al. (2011), using US Coast Guard data with matched comparisons: recreational boaters who fell overboard wearing a personal flotation device had about half the drowning risk (adjusted RR 0.51, 95% CI 0.35–0.74).", "sources": "Cummings P et al. (2011). Association between wearing a personal floatation device and death by drowning among recreational boaters. Injury Prevention. <https://doi.org/10.1136/ip.2010.028688>", "notes": "**Canada:** Transport Canada requires a properly sized lifejacket or PFD for everyone aboard; wear it, don't sit on it — cold water kills fast. The A grade covers lifejackets only; \"never look away\" is universal consensus (C grade — no trial will ever be run).", "urls": ["https://doi.org/10.1136/ip.2010.028688"]}, {"id": "01-013", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 13, "title": "From 60 on, train balance and leg strength; fix up the bathroom and stairs", "money": "low", "time": "high", "willpower": "yes", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Balance or tai chi practice 2–3 times a week, 30 minutes each. Grab bars, non-slip mats, and night lights cost $20–$100. The hard part is keeping it up for years.", "plain": "Regular balance exercise cuts the number of falls by about 23% and the number of people who fall by 15%; tai chi cuts fall risk about 29%; a home safety assessment and fixes cut falls about 20%. More than half of older adults' falls happen at home.", "benefit_text": "Cochrane (Sherrington 2019; 108 trials, 23,407 people): exercise cut fall rate 23% (RaR 0.77, 95% CI 0.71–0.83) and fallers 15% (RR 0.85); tai chi RR 0.71 (29% fewer falls). Home safety assessment and modification: RR 0.81.", "sources": "Sherrington C et al. (2019). Exercise for preventing falls in older people living in the community. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD012424.pub2>; Gillespie LD et al. (2012). Interventions for preventing falls in older people living in the community. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD007146.pub3>", "notes": "This applies to community-dwelling adults 60+. The studies counted falls, not deaths — but the road from a fall to a hip fracture to death is short in older adults. **Canada:** Ask your family doctor about community falls-prevention programs and occupational-therapy home assessments.", "urls": ["https://doi.org/10.1002/14651858.CD007146.pub3", "https://doi.org/10.1002/14651858.CD012424.pub2"]}, {"id": "01-014", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 14, "title": "Get tested for hepatitis B; vaccinate if you have no antibodies", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "A blood test costs roughly $20–$40. The adult 3-dose hepatitis B series costs about $60–$150, done within six months.", "plain": "In the 30-year Qidong trial, newborn hepatitis B vaccination cut liver cancer 84% and chronic infection 72%. Adults: get tested, and take the 3 shots if you lack antibodies. The vaccine does not help if you are already infected — then you need liver follow-up instead.", "benefit_text": "Qu et al. (2014): neonatal vaccination — primary liver cancer down 84% (95% CI 23–97%), HBsAg positivity down 72% (95% CI 68–75%) over 30 years.", "sources": "Qu C et al. (2014). Efficacy of neonatal HBV vaccination on liver cancer and other liver diseases over 30-year follow-up of the Qidong hepatitis B intervention study. PLoS Medicine. <https://doi.org/10.1371/journal.pmed.1001774>", "notes": "**Ontario:** Hepatitis B vaccine is in the grade 7 school program; adults at risk (health workers, household contacts of carriers, travellers) can get it at pharmacies and travel clinics. The 84% figure comes from newborn vaccination — adults vaccinated later get protection against new infection, not that number. HBsAg positive on your lab slip means already infected.", "urls": ["https://doi.org/10.1371/journal.pmed.1001774"]}, {"id": "01-015", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 15, "title": "Nail, splinter, or soil-contaminated wound — get it treated the same day, and ask about tetanus", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A clinic visit plus wound care is covered by OHIP at a family doctor or walk-in clinic. A booster or immunoglobulin, if needed, is low-cost.", "plain": "Tetanus kills about 1 in 10 who get it. Deep, soil-contaminated wounds are highest risk. Dirty wound plus 5+ years since your last shot means a booster; 10+ years since the shot means a booster whatever the wound.", "benefit_text": "US CDC: about 1 in 10 US tetanus cases are fatal. Wound risk tiers and booster rules: 3+ doses with last shot under 5 years — nothing needed; 5–10 years — booster for high-risk wounds; 10+ years — booster regardless; incomplete series — complete it, plus immunoglobulin for high-risk wounds.", "sources": "US CDC, Tetanus. <https://www.cdc.gov/tetanus/about/index.html>", "notes": "**Canada:** Routine Tdap is given in grade 7; adults need a Td booster every 10 years (NACI). Let the doctor decide — bring your best guess of when your last tetanus shot was. \"One childhood series protects for life\" is false.", "urls": ["https://www.cdc.gov/tetanus/about/index.html"]}, {"id": "01-016", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 16, "title": "Get the HPV vaccine, as early as possible", "money": "high", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free in Ontario's grade 7 school program. Privately, Gardasil-9 is roughly $200+ per dose for 2–3 doses.", "plain": "In Sweden's study, those vaccinated before 17 had invasive cervical cancer rates about 88% lower than the unvaccinated; vaccinated at 17–30, about 53% lower. Earlier is better — and you still need screening afterwards.", "benefit_text": "Lei et al. (2020): invasive cervical cancer incidence — vaccinated before 17, IRR 0.12 (95% CI 0.00–0.34, 88% lower); vaccinated at 17–30, IRR 0.47 (95% CI 0.27–0.75, 53% lower).", "sources": "Lei J et al. (2020). HPV Vaccination and the Risk of Invasive Cervical Cancer. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa1917338>", "notes": "**Ontario:** Gardasil-9 is free in the grade 7 school program (with catch-up through grade 12). Adults pay out of pocket — some private drug plans cover it. The vaccine does not replace cervical screening (see item 18).", "urls": ["https://doi.org/10.1056/NEJMoa1917338"]}, {"id": "01-017", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 17, "title": "Breast cancer screening from 40: a mammogram every 2–3 years", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free — covered by OHIP. Half a day every 2–3 years.", "plain": "Canada's 2024 guideline: women 40–74 should have the choice of a mammogram every 2–3 years, made as an informed decision. Above that age range, and for add-on ultrasound and MRI with dense breasts, the evidence is judged insufficient — you can skip the upsell in checkup packages.", "benefit_text": "Canadian Task Force on Preventive Health Care (2024): conditional recommendation — women aged 40–74 may choose screening mammography every 2–3 years after informed discussion of benefits and harms.", "sources": "Canadian Task Force on Preventive Health Care (2024) breast cancer screening draft recommendations — mammography accessible every 2–3 years for ages 40–74 after shared decision-making; 75+ not recommended; no supplemental MRI/ultrasound for dense breasts (final guideline pending at write time). <https://canadiantaskforce.ca/guidelines/published-guidelines/breast-cancer-update-2024/>", "notes": "**Ontario:** Book through your family doctor or the Ontario Breast Screening Program, which covers ages 40–74. With a parent, sibling, or child who had breast cancer, or a BRCA mutation, you are high-risk — get a personal plan from your doctor; this item does not apply.", "urls": ["https://canadiantaskforce.ca/guidelines/published-guidelines/breast-cancer-update-2024/"]}, {"id": "01-018", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 18, "title": "Cervical cancer screening from 25: HPV testing first", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free via the Ontario Cervical Screening Program. A few minutes for sampling; every 5 years if negative.", "plain": "In rural India, women who had just one lifetime HPV test had cervical cancer death rates about 48% lower and advanced cancers about 53% lower. Vaccinated women still need screening — the vaccine doesn't cover every virus type.", "benefit_text": "Sankaranarayanan et al. (2009), cluster-randomized trial of women 30–59: one round of HPV screening — cervical cancer death HR 0.52 (95% CI 0.33–0.83, 48% lower); advanced cancer HR 0.47 (95% CI 0.32–0.69, 53% lower).", "sources": "Sankaranarayanan R et al. (2009). HPV screening for cervical cancer in rural India. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa0808516>", "notes": "**Ontario:** Since March 2025, Ontario uses primary HPV screening: ages 25+, every 5 years if negative. Rare among screening trials — it was randomized and measured deaths directly after a single round.", "urls": ["https://doi.org/10.1056/NEJMoa0808516"]}, {"id": "01-019", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 19, "title": "Colorectal cancer screening from 45: FIT stool test or colonoscopy", "money": "low", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "The FIT kit is free via ColonCancerCheck, every 2 years. Colonoscopy is OHIP-covered when indicated; prep takes a day.", "plain": "A stool FIT test every one to two years means about 16% lower colorectal cancer death (25% in people screened at least once). In the NordICC trial, being invited to one colonoscopy cut 10-year incidence from 1.20% to 0.98%.", "benefit_text": "Cochrane: faecal occult blood screening — colorectal cancer death RR 0.84 (16% lower, 95% CI 0.78–0.90); at least one round RR 0.75 (25% lower). NordICC trial: invitation to colonoscopy — 10-year incidence 1.20% vs 0.98%, RR 0.82 (95% CI 0.70–0.93).", "sources": "Hewitson P et al. (2007). Screening for colorectal cancer using the faecal occult blood test, Hemoccult. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD001216.pub2>; Bretthauer M et al. (2022). Effect of Colonoscopy Screening on Risks of Colorectal Cancer and Related Death. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa2208375>", "notes": "**Ontario:** ColonCancerCheck mails FIT kits from age 45 (since July 2026), every 2 years. Disputed: NordICC measured by invitation — cancer death 0.28% vs 0.31% (RR 0.90, not significant), so colonoscopy's mortality benefit was previously overstated; the FIT mortality evidence is harder. Family history means starting earlier — ask your doctor.", "urls": ["https://doi.org/10.1002/14651858.CD001216.pub2", "https://doi.org/10.1056/NEJMoa2208375"]}, {"id": "01-020", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 20, "title": "Heart patients and seniors: a flu shot every fall", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free in Ontario for everyone 6 months and older. Once each fall.", "plain": "In a trial of heart-attack survivors, death within a year fell from 4.9% to 2.9% with the flu shot. Heart patients and older adults: get one every fall.", "benefit_text": "Fröbert et al. (2021), 2,571 post-MI patients randomized, double-blind: 12-month total mortality 2.9% (vaccine) vs 4.9% (placebo), HR 0.59 (95% CI 0.39–0.89). Meta-analysis: major cardiovascular events RR 0.66 (95% CI 0.53–0.83).", "sources": "Fröbert O et al. (2021). Influenza Vaccination After Myocardial Infarction. Circulation. <https://doi.org/10.1161/CIRCULATIONAHA.121.057042>; Behrouzi B et al. (2022). Association of Influenza Vaccination With Cardiovascular Risk. JAMA Network Open. <https://doi.org/10.1001/jamanetworkopen.2022.8873>", "notes": "**Ontario:** Free every fall at pharmacies, clinics, and public health units. Disputed: the A grade covers heart patients only — for otherwise healthy seniors, Cochrane rates the mortality evidence very low (one flu season's illness 6% → 2.4%, low-certainty).", "urls": ["https://doi.org/10.1001/jamanetworkopen.2022.8873", "https://doi.org/10.1161/CIRCULATIONAHA.121.057042"]}, {"id": "01-021", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 21, "title": "From 50 on, get the shingles vaccine", "money": "high", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Two doses of Shingrix cost roughly $300+ in total privately. Publicly funded in Ontario for ages 65–70.", "plain": "In the trial, the vaccine blocked 97% of shingles cases, about the same in every age group. Sore arms and fevers after the shot are common. Shingles rarely kills — what you are buying is avoiding months of nerve pain.", "benefit_text": "Lal et al. (2015), 15,400 people across 18 countries randomized, 3.2 years average follow-up: 6 vs 210 shingles cases — overall efficacy about 97% (97.2%, 95% CI 93.7–99.0), 96.6%–97.9% across age groups.", "sources": "Lal H, Cunningham AL, Godeaux O, et al. (2015). Efficacy of an adjuvanted herpes zoster subunit vaccine in older adults. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa1501184>", "notes": "**Ontario:** Shingrix is publicly funded for ages 65–70. Ages 50–64 and 71+ pay out of pocket — ask your pharmacy. It ranks lower on cost-effectiveness because it is expensive, and the payoff is pain avoided, not death avoided. Grade 3 symptoms after vaccination: 17.0% vs 3.2%.", "urls": ["https://doi.org/10.1056/NEJMoa1501184"]}, {"id": "01-022", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 22, "title": "From 65 on, get the pneumococcal vaccine", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free for 65+ in Ontario (publicly funded).", "plain": "In a Dutch trial of 84,500 seniors, the vaccine blocked about 46% of the pneumonia types it covers and 75% of the most dangerous invasive infections. It did nothing against all-cause pneumonia — don't expect it to prevent every pneumonia.", "benefit_text": "Bonten et al. (2015), 84,500 Dutch adults 65+ randomized: 45.6% efficacy (about 46%, 95.2% CI 21.8–62.5) against vaccine-type pneumonia, 75.0% (about 75%, 95% CI 41.4–90.8) against invasive pneumococcal disease, no effect on all-cause pneumonia.", "sources": "Bonten MJ, Huijts SM, Bolkenbaas M, et al. (2015). Polysaccharide conjugate vaccine against pneumococcal pneumonia in adults. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa1408544>", "notes": "**Ontario:** PCV21 (Capvaxive) is publicly funded for 65+ from August 17, 2026. Caveat: the trial used the 13-valent conjugate vaccine, not the 21-valent one now funded — the numbers don't transfer directly.", "urls": ["https://doi.org/10.1056/NEJMoa1408544"]}, {"id": "01-023", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 23, "title": "Test for H. pylori; eradicate it if positive", "money": "low", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "A breath test costs roughly $100–$200. Eradication is four drugs for two weeks, a few hundred dollars. The hard part is taking every dose on schedule.", "plain": "In a 22-year study, wiping out H. pylori cut later stomach cancer about in half and stomach-cancer death about 38%. Test once for one to two hundred dollars; treatment is two weeks of pills. Test and treat the household together — reinfection happens.", "benefit_text": "Li et al. (2019), Linqu randomized trial with 22-year follow-up: eradication — stomach cancer OR 0.48 (95% CI 0.32–0.71), stomach-cancer death HR 0.62 (38% lower, 95% CI 0.39–0.99).", "sources": "Li WQ et al. (2019). Effects of Helicobacter pylori treatment and vitamin and garlic supplementation on gastric cancer incidence and mortality. BMJ. <https://doi.org/10.1136/bmj.l5016>", "notes": "**Canada:** The breath test is available through your family doctor (OHIP-covered with a requisition). The trial was in a high-incidence region — in low-incidence areas the absolute payoff is smaller.", "urls": ["https://doi.org/10.1136/bmj.l5016"]}, {"id": "01-024", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 24, "title": "Heavy smokers: a low-dose chest CT every year", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "OHIP-covered when eligible through the Ontario Lung Screening Program. Ten minutes per scan.", "plain": "For eligible heavy smokers, yearly low-dose CT cut lung-cancer death 20% and total death 6.7% versus chest X-ray. The price: 24% got a suspicious finding, and 96.4% of those were false alarms, plus the anxious weeks. Never-smokers: this buys only worry.", "benefit_text": "US NLST randomized trial, 53,454 people aged 55–74 with 30+ pack-years, quit <15 years: low-dose CT vs chest X-ray — lung-cancer death down 20.0% (about 20%, 95% CI 6.8–26.7), total mortality down 6.7% (95% CI 1.2–13.6); 24% had a positive screen, 96.4% of those false positives.", "sources": "National Lung Screening Trial Research Team (2011). Reduced Lung-Cancer Mortality with Low-Dose Computed Tomographic Screening. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa1102873>", "notes": "**Ontario:** The Ontario Lung Screening Program covers ages 55–80 who smoked daily for 20+ years (currently smoking or quit under 15 years ago) — referral through your doctor. Only for high-risk smokers.", "urls": ["https://doi.org/10.1056/NEJMoa1102873"]}, {"id": "01-025", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 25, "title": "Feeling depressed or suicidal: call 9-8-8, and keep lethal means out of reach", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free call. Lock up medications; don't store pesticides at home.", "plain": "Removing access works and the evidence keeps strengthening: limiting analgesic pack sizes cut analgesic suicides 43%; barriers at jumping hotspots cut them 86%. The urge usually lasts minutes to hours — one extra step of distance is itself the intervention.", "benefit_text": "Zalsman et al. (2016), 10-year systematic review: restricting means — analgesic-related suicide down 43% after pack-size limits; 86% down (79–91%) after barriers at hotspots; school-based awareness programs — attempts down ~55% (OR 0.45, 95% CI 0.24–0.85).", "sources": "Zalsman G et al. (2016). Suicide prevention strategies revisited: 10-year systematic review. Lancet Psychiatry. <https://doi.org/10.1016/S2215-0366(16)30030-X>", "notes": "**Canada:** Call or text 9-8-8 any time — free, 24/7, English and French. Youth can also call Kids Help Phone at 1-800-668-6868. Graded B because most means-restriction evidence is before/after policy comparisons, and helplines themselves have no mortality-trial evidence. What happens after an attempt: items 32 and 33.", "urls": ["https://doi.org/10.1016/S2215-0366(16"]}, {"id": "01-026", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 26, "title": "Keep an extinguisher, fire blanket, escape masks, and a first-aid kit — check yearly", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Roughly $100–$200 for the set, bought once. Ten minutes a year to check.", "plain": "Studies of home safety visits cut injury rates about a quarter. Equipment handed out without guidance did worse — the visit and the fixes matter more than the shopping.", "benefit_text": "Cochrane (Kendrick 2012; 98 studies, 2.6 million people): home safety interventions — injury rate IRR 0.89 (95% CI 0.78–1.01); home-visit interventions IRR 0.75 (95% CI 0.62–0.91).", "sources": "Kendrick D et al. (2012). Home safety education and provision of safety equipment for injury prevention. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD005014.pub3>", "notes": "**Canada:** Buy extinguishers with ULC/CSA marks; the pressure gauge needle should sit in the green zone. Benefit graded mid, not high: in the same review, education-only interventions (IRR 0.78) did no worse than equipment giveaways. Smoke and CO alarms: item 3.", "urls": ["https://doi.org/10.1002/14651858.CD005014.pub3"]}, {"id": "01-027", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 27, "title": "Visible blood in your urine — even once, even painless, even if it clears — get checked", "money": "low", "time": "mid", "willpower": "no", "benefit": "low", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Urinalysis plus ultrasound is a few hundred dollars; cystoscopy around $1,000 if the doctor wants it. OHIP-covered with referral.", "plain": "Visible blood in the urine means bladder cancer in about 2.8% of people over 60 and 1.2% at ages 40–59. Not high — but high enough for one check, even if it doesn't hurt and stops the next day.", "benefit_text": "Price et al. (2014), UK primary-care records (4,915 bladder cancers, 21,718 controls): positive predictive value of visible haematuria — 2.8% (95% CI 2.5–3.1) at 60+, 1.2% (0.6–2.3) at 40–59. Microscopic haematuria: OR 20 (95% CI 12–33).", "sources": "Price SJ, Shephard EA, Stapley SA, Barraclough K, Hamilton WT (2014). Non-visible versus visible haematuria and bladder cancer risk. British Journal of General Practice. <https://doi.org/10.3399/bjgp14X681409>", "notes": "\"Painless\" is the key word — stones and infections usually come with cramping or burning; tumours bleed silently and intermittently, which is why people ignore them. Being on blood thinners is not a reason to skip the check. Benefit graded small: this is a detection rate, with no measured mortality effect.", "urls": ["https://doi.org/10.3399/bjgp14X681409"]}, {"id": "01-028", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 28, "title": "Erectile trouble? Check your heart first, not just \"that department\"", "money": "low", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "A doctor visit is OHIP-covered; blood pressure plus bloodwork is a couple of hundred dollars uninsured. One trip, results in days.", "plain": "Men with erectile dysfunction later have about 44% more cardiovascular events and 62% more heart attacks — and it often shows up before chest pain. Get blood pressure, glucose, and lipids checked instead of papering it over. Younger men show the biggest relative gaps.", "benefit_text": "Vlachopoulos et al. (2013), meta-analysis of 14 cohorts (92,757 men, 6.1 years average): ED vs no ED — total cardiovascular events RR 1.44 (44% more, 95% CI 1.27–1.63), MI RR 1.62 (62% more, 1.34–1.96), cerebrovascular events RR 1.39 (1.23–1.57), all-cause death RR 1.25 (1.12–1.39).", "sources": "Vlachopoulos CV, Terentes-Printzios DG, Ioakeimidis NK, Aznaouridis KA, Stefanadis CI (2013). Prediction of cardiovascular events and all-cause mortality with erectile dysfunction. Circulation: Cardiovascular Quality and Outcomes. <https://doi.org/10.1161/CIRCOUTCOMES.112.966903>", "notes": "These are associations from follow-up studies, not trials — \"44% more\" is a group gap, not a personal sentence. Occasional misses don't count; three months of persistence does. Real ED drugs are prescription-only and clash fatally with nitrates (nitroglycerin-type drugs); skip the online \"supplements.\" How to improve: item 29.", "urls": ["https://doi.org/10.1161/CIRCOUTCOMES.112.966903"]}, {"id": "01-029", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 29, "title": "Lose weight, quit smoking, control blood pressure and glucose — erections improve too", "money": "0", "time": "high", "willpower": "yes", "benefit": "low", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free, and may save money. The hard part is years of eating discipline, moving, and staying quit.", "plain": "Taming cardiovascular risk factors lifts the erectile-function questionnaire (IIEF-5) by about 2.66 points — a real but modest improvement.", "benefit_text": "Gupta et al. (2011), meta-analysis of 6 randomized trials (740 men): lifestyle or risk-factor treatment — IIEF-5 up 2.66 points (95% CI 1.86–3.47); lifestyle-only trials (597 men) up 2.40 (1.19–3.61).", "sources": "Gupta BP, Murad MH, Clifton MM, Prokop L, Nehra A, Kopecky SL (2011). The effect of lifestyle modification and cardiovascular risk factor reduction on erectile dysfunction. Archives of Internal Medicine. <https://doi.org/10.1001/archinternmed.2011.440>", "notes": "Only 740 men and mixed interventions, so direction is clear, size varies. Benefit graded small: the endpoint is a questionnaire score, with no disease numbers attached. The same moves have hard endpoints elsewhere: quitting (Chapter 2, item 1), weight (Chapter 2, item 33), blood pressure (this chapter, item 7).", "urls": ["https://doi.org/10.1001/archinternmed.2011.440"]}, {"id": "01-030", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 30, "title": "Condoms, every time, start to finish — and don't share needles", "money": "low", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "About $1 each; free at sexual health clinics. The hard part isn't money — it's using one every single time, from the start.", "plain": "Consistent every-time use cuts HIV transmission between partners about 71%. On-and-off use is barely better than none. The same protection covers syphilis, gonorrhoea, and chlamydia. Sharing needles — for drugs, tattoos, piercings — is a separate high-efficiency route.", "benefit_text": "Giannou et al. (2016), 25 studies, 10,676 serodiscordant heterosexual couples: consistent use vs never — RR 0.29 (71% fewer, 95% CI 0.20–0.43); consistent vs inconsistent — RR 0.23 (95% CI 0.13–0.40). Authors' conclusion: consistent use cuts HIV transmission by 70%+.", "sources": "Giannou FK, Tsiara CG, Nikolopoulos GK, et al. (2016). Condom effectiveness in reducing heterosexual HIV transmission. Expert Review of Pharmacoeconomics & Outcomes Research. <https://doi.org/10.1586/14737167.2016.1102635>", "notes": "**Ontario:** Free condoms at public health sexual health clinics. High-risk groups can also ask about PrEP — preventive medication (item 38); it needs >70% adherence to work (RR 0.30) and is prescription-only, so ask a doctor, don't order online.", "urls": ["https://doi.org/10.1586/14737167.2016.1102635"]}, {"id": "01-031", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 31, "title": "After high-risk exposure, get one HIV test — Ontario's is free and confidential", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. One blood draw at public health or a designated clinic. The hard part is walking in.", "plain": "Ontario offers free anonymous HIV testing, and staff may not disclose your name, address, results. A positive result is not a death sentence: people on treatment with undetectable virus do not pass it to sex partners — one study followed 782 couples through 76,088 condomless acts with zero partner transmissions.", "benefit_text": "Rodger et al. (2019), PARTNER study: 782 serodiscordant gay couples, 1,593 couple-years, 76,088 condomless sex acts — after phylogenetic analysis, zero transmissions came from the partner. WHO: people on antiretroviral therapy with undetectable viral load do not transmit HIV to sexual partners.", "sources": "Rodger AJ, Cambiano V, Bruun T, et al. (2019). Risk of HIV transmission through condomless sex in serodifferent gay couples with the HIV-positive partner taking suppressive antiretroviral therapy (PARTNER). The Lancet. <https://doi.org/10.1016/S0140-6736(19)30418-0>", "notes": "**Ontario:** Find anonymous testing through the AIDS & Sexual Health Info Line: 1-800-668-2437 (Toronto: 416-392-2437). <https://www.cleo.on.ca/en/publications/hivtest/all> Window periods: nucleic-acid test ~1 week, 4th-generation antigen/antibody ~2 weeks, antibody ~3 weeks — test at 2+ weeks, repeat in 2–4 weeks, and 3 months after the last exposure rules it out. A reactive self-test is not a diagnosis — confirm at public health. Disclosing to sex partners is a legal duty; discrimination in marriage, work, care, and school is prohibited.", "urls": ["https://doi.org/10.1016/S0140-6736(19", "https://www.cleo.on.ca/en/publications/hivtest/all"]}, {"id": "01-032", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 32, "title": "When the thought appears, tell one person nearby — hand over the next hour", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. The hard part is speaking up in the moment and admitting you shouldn't be alone for the next few hours.", "plain": "Nearly half of attempt survivors say they went from first thought to act within 10 minutes — so the minutes you need to survive are usually just these. Three-quarters had contact with someone in that window but said nothing. Most people who self-harm do not later die by suicide (about 2% at 1 year, 7% past 9 years) — but their risk stays hundreds of times above average, so still get care.", "benefit_text": "Deisenhammer et al. (2009): 82 attempt survivors interviewed within 3 days — 47.6% went from first thought to attempt in ≤10 minutes; 76.8% had contact with a partner, family, or friend in that window. Owens et al. (2002), 90 follow-up studies: median 16% repeated self-harm without dying at 1 year; 2% died by suicide at 1 year; ~7% at 9+ years.", "sources": "Deisenhammer EA, Ing CM, Strauss R, Kemmler G, Hinterhuber H, Weiss EM (2009). The duration of the suicidal process. Journal of Clinical Psychiatry. <https://doi.org/10.4088/JCP.07m03904>; Owens D, Horrocks J, House A (2002). Fatal and non-fatal repetition of self-harm: systematic review. British Journal of Psychiatry. <https://doi.org/10.1192/bjp.181.3.193>", "notes": "**Canada:** Call or text 9-8-8 any time. Graded B: 82 people from one hospital relying on recall, and a median across 90 heterogeneous studies — \"most survive\" describes the group, never a guarantee for one person. Move lethal means away and call 9-8-8: item 25. What survival can cost: item 33.", "urls": ["https://doi.org/10.1192/bjp.181.3.193", "https://doi.org/10.4088/JCP.07m03904"]}, {"id": "01-033", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 33, "title": "Don't count on being \"saved\": pesticide and CO poisoning leave lungs and brains behind", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. Just learn this before anything happens.", "plain": "Paraquat has no antidote — over four in ten who drink it die. It scars the lungs and injures the kidneys and liver. Of carbon-monoxide poisoning survivors, nearly half have thinking problems at six weeks without hyperbaric oxygen — and a quarter even with it.", "benefit_text": "Gawarammana & Buckley (2011), systematic review: paraquat has no effective treatment — no gastric lavage; haemodialysis/haemoperfusion unlikely to change the course; steroids and immunosuppressants weakly evidenced; \"case fatality was high in all centres, despite large variations in treatment.\" Chowdhury et al. (2026): 257 analyzable cases in Bangladesh, 43.2% dead. Weaver et al. (2002), double-blind randomized trial (76 per arm): cognitive sequelae at 6 weeks — hyperbaric oxygen 19/76 (25.0%), normobaric oxygen 35/76 (46.1%), adjusted OR 0.45 (95% CI 0.22–0.92).", "sources": "Gawarammana IB, Buckley NA (2011). Medical management of paraquat ingestion. British Journal of Clinical Pharmacology. <https://doi.org/10.1111/j.1365-2125.2011.04026.x>; Weaver LK, Hopkins RO, Chan KJ, et al. (2002). Hyperbaric oxygen for acute carbon monoxide poisoning. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa013121>", "notes": "**Canada:** Paraquat (Gramoxone 200 SL) is a restricted-use pesticide here — certified applicators only, closed-system handling; it is not a household product. <https://www.canada.ca/en/health-canada/services/consumer-product-safety/reports-publications/pesticides-pest-management/fact-sheets-other-resources/paraquat.html> Never induce vomiting after swallowing pesticides or pills — bring the container and call the Ontario Poison Centre at 1-844-764-7669 or 911. If a CO alarm sounds: get everyone out and call 911. Graded B because the studies cover poisoning patients generally, not only suicide attempts — but no method leaves no sequelae. This book does not compare methods' lethality or describe any method.", "urls": ["https://doi.org/10.1056/NEJMoa013121", "https://doi.org/10.1111/j.1365-2125.2011.04026.x", "https://www.canada.ca/en/health-canada/services/consumer-product-safety/reports-publications/pesticides-pest-management/fact-sheets-other-resources/paraquat.html"]}, {"id": "01-034", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 34, "title": "Don't bet \"a few days in bed\" on a fall from height: most ICU survivors pay for years", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. Just see the bill clearly first.", "plain": "Of fall patients who reached a trauma ICU, only 5.5% died — but nearly half injured three-plus body regions, over a third needed ventilators, and the longest ICU stay was 132 days. Half fell from 3 metres and under. Under six in ten of the severely injured ever returned to work.", "benefit_text": "Chen et al. (2025), 289 trauma-ICU fall admissions: median height 3 m, median ISS 24, 47.1% with 3+ injured regions, 36% ventilated (median 103.5 hours), median ICU stay 8 days (range 1–132), 5.5% dead in hospital or at 30 days. Simmel et al. (2020), 84 polytrauma patients (ISS ≥25): 58% returned to work.", "sources": "Chen Y, Li W, Wang X, et al. (2025). Clinical features and prognostic predictors for patients admitted to trauma intensive care unit due to fall from height in South Xinjiang. International Journal of Emergency Medicine. <https://doi.org/10.1186/s12245-025-00959-4>; Simmel S et al. (2020). Prädiktion der Rückkehr zur Arbeit nach Polytrauma. Die Rehabilitation. <https://doi.org/10.1055/a-0977-6853>", "notes": "Graded B: the fall cohort is one hospital's records without separating accidents from self-harm, and the return-to-work cohort is 84 German patients — neither describes what happens to one person after a jump. When the thought appears: item 32 and 9-8-8. What poisoning costs: item 33.", "urls": ["https://doi.org/10.1055/a-0977-6853", "https://doi.org/10.1186/s12245-025-00959-4"]}, {"id": "01-035", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 35, "title": "Don't trade a kidney for cash: the remaining one does double duty, and 86% of sellers say their health worsened", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. Just see the bill clearly first.", "plain": "Screened living donors with years of follow-up: 30.8 per 10,000 reached kidney failure in 15 years, versus 3.9 per 10,000 equally healthy non-donors. In Norway, donors' all-cause death ran about 30% higher. Kidney sellers in India — no screening, no follow-up: 86% said their health was worse six years later, and three-quarters were still in debt.", "benefit_text": "Muzaale et al. (2014), 96,217 US living donors vs 20,024 equally healthy non-donors: 15-year kidney-failure risk 30.8 vs 3.9 per 10,000. Mjøen et al. (2014), Norway: donors' all-cause death HR 1.30 (about 30% higher, 95% CI 1.11–1.52), cardiovascular death HR 1.40, kidney failure HR 11.38. Goyal et al. (2002), 305 sellers in Chennai surveyed ~6 years later: 96% sold to repay debt (average $1,070 received); household income down a third; 86% reported worse health; 79% would not recommend it.", "sources": "Muzaale AD et al. (2014). Risk of end-stage renal disease following live kidney donation. JAMA. <https://doi.org/10.1001/jama.2013.285141>; Mjøen G et al. (2014). Long-term risks for kidney donors. Kidney International. <https://doi.org/10.1038/ki.2013.460>; Goyal M et al. (2002). Economic and health consequences of selling a kidney in India. JAMA. <https://doi.org/10.1001/jama.288.13.1589>", "notes": "**Canada:** Buying or selling organs is illegal — the Trillium Gift of Life Network Act s.10(1) prohibits it. Legitimate living donation is unpaid, screened, and followed. Disputed: one study using ordinary people as the comparison found donors' survival and kidney-failure risk similar to the general public — the disagreement is about whom to compare against, and all studies agree the absolute risk is small (30.8 per 10,000 at 15 years). The point is what the remaining kidney pays: hypertension and protein in the urine — and black-market sellers get none of the screening, follow-up, or hospital backup.", "urls": ["https://doi.org/10.1001/jama.2013.285141", "https://doi.org/10.1001/jama.288.13.1589", "https://doi.org/10.1038/ki.2013.460"]}, {"id": "01-036", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 36, "title": "Don't pick up, open, or sell metal parts of unknown origin — keep away from the trefoil symbol", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. Walk around unrecognized metal cylinders, lead canisters, or parts stripped off equipment — don't pocket them, don't open them.", "plain": "Radiation has no smell, colour, heat, and most sources look like ordinary metal — \"looks fine\" is not a test. The odds of meeting one are tiny (under 1 incident per 10,000 sources per year), but meeting one is irreversible: in 1987 Brazil, a scavenged clinic radiotherapy unit killed 4 people.", "benefit_text": "IAEA, Goiânia 1987: a 50.8 TBq caesium-137 source was removed and its capsule ruptured — ~112,000 people monitored, 249 contaminated (129 moderate-to-severe, 50 under close medical watch), 4 dead. China's 2025 figures: ~178,000 sources in use, incident rate under 1 per 10,000 per year.", "sources": "International Atomic Energy Agency (1988). The Radiological Accident in Goiânia. <https://www-pub.iaea.org/MTCD/Publications/PDF/Pub815_web.pdf>", "notes": "**Canada:** If you find one — keep away, remember the location, don't move it, call 911. Sealed sources are regulated by the Canadian Nuclear Safety Commission. Distance and time are the only real protection; a pocket or plastic bag does nothing. X-ray and CT machines make radiation only when powered — the danger is the sealed source inside equipment like radiotherapy units, industrial gamma radiography cameras, and gauges. Scrap, demolition, and construction workers face the highest risk: walk around any trefoil-marked exclusion zone.", "urls": ["https://www-pub.iaea.org/MTCD/Publications/PDF/Pub815_web.pdf"]}, {"id": "01-037", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 37, "title": "Gambling past borrowed money with low mood: call for help first, then hand your cards and passwords to family", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free call. Hand bank cards, payment passwords, and lending apps to family. The hard part is admitting you've lost control.", "plain": "People treated for gambling disorder die by suicide at 15 times the peer rate and die overall at 1.8 times. Depression is the signal that predicts suicide. Borrowing to gamble plus persistently low mood: call now.", "benefit_text": "Karlsson & Håkansson (2018), Swedish national registers, 2,099 people diagnosed with gambling disorder 2005–2016: all-cause mortality SMR 1.8, suicide SMR 15 (67 deaths, 21 suicides in follow-up); depression predicted suicide death. 2023 corrigendum: men 12.1×, women 16.1×.", "sources": "Karlsson A, Håkansson A (2018). Gambling disorder, increased mortality, suicidality, and associated comorbidity. Journal of Behavioral Addictions. <https://doi.org/10.1556/2006.7.2018.112>", "notes": "**Ontario:** ConnexOntario at 1-866-531-2600 — free, 24/7, for gambling, alcohol, and drugs. OLG offers self-exclusion. In crisis, call or text 9-8-8. Graded B: a single study of people sick enough to reach specialist care — 15× does not apply to everyone who plays cards. Handing money to family is practical wisdom (C grade), not trial evidence.", "urls": ["https://doi.org/10.1556/2006.7.2018.112"]}, {"id": "01-038", "chapter_num": 1, "chapter_title": "Don't Die Young", "chapter_file": "01-dont-die-young.md", "number": 38, "title": "Men who have sex with men with high-risk exposure: ask about PrEP, and take it on schedule — 70%+ fewer infections", "money": "high", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "A prescription drug. Generic PrEP is covered by ODB for eligible Ontarians; otherwise roughly $250+/month privately. Baseline HIV, kidney, and hepatitis B tests, then check-ups every 3 months. The hard part is taking it every day.", "plain": "Taken before exposure, this antiviral cuts HIV infection by at least 70% in people who take it consistently. On-and-off use barely works. It is prescription-only: get tested first, then refilled on schedule. It does not block syphilis and gonorrhoea — keep using condoms.", "benefit_text": "Fonner et al. (2016), WHO meta-analysis: overall RR 0.49 (95% CI 0.33–0.73); trials with >70% adherence RR 0.30 (0.21–0.45); <40% adherence RR 0.95 — no effect. iPrEx: 44% fewer infections (95% CI 15–63); PROUD: 86% fewer (90% CI 64–96); IPERGAY on-demand: 86% fewer (95% CI 40–98).", "sources": "Grant RM et al. (2010). Preexposure chemoprophylaxis for HIV prevention in men who have sex with men. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa1011205>; Fonner VA et al. (2016). Effectiveness and safety of oral HIV preexposure prophylaxis for all populations. AIDS. <https://doi.org/10.1097/QAD.0000000000001145>", "notes": "**Ontario:** Ask at a sexual health clinic, your doctor, or the AIDS & Sexual Health Info Line (1-800-668-2437). Generic tenofovir-emtricitabine is covered under ODB for those eligible (seniors, social assistance; others via the Trillium deductible or private plans). Must confirm HIV-negative before starting — self-test kits don't count, and starting while infected breeds resistance. Hepatitis B carriers need testing first (stopping can flare hepatitis). On-demand dosing is WHO-recommended only for men who have sex with men averaging under twice a week. After exposure, post-exposure prophylaxis within 72 hours: see Chapter 13.", "urls": ["https://doi.org/10.1056/NEJMoa1011205", "https://doi.org/10.1097/QAD.0000000000001145"]}, {"id": "02-001", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 1, "title": "Quit smoking, the earlier the better", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free — and it saves money. A pack in Ontario runs about $15–$20, so a pack a day is thousands a year back in your pocket. The hard part is the withdrawal weeks.", "plain": "Smokers live ten-plus years less than never-smokers. Quitting before 40 wipes out about 90% of the extra death risk from continued smoking. Quit at 25–34 and you gain back about 10 years; at 35–44, about 9; at 45–54, about 6.", "benefit_text": "Jha et al. (2013), US cohort: current smokers vs never-smokers — 10+ years shorter life expectancy; quitting before 40 avoids ~90% of the excess mortality of continued smoking. Years gained: ~10 (quit 25–34), ~9 (35–44), ~6 (45–54).", "sources": "Jha P et al. (2013). 21st-century hazards of smoking and benefits of cessation in the United States. New England Journal of Medicine. <https://doi.org/10.1056/NEJMsa1211128>", "notes": "**Ontario:** Smokers' Helpline at 1-877-513-5333 — free quit coaches. How to quit: medication (item 3), a quit date (item 4), counselling (item 5). Secondhand smoke kills too: item 2.", "urls": ["https://doi.org/10.1056/NEJMsa1211128"]}, {"id": "02-002", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 2, "title": "No smoking in the home or car — and no guests smoking indoors", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free, no time. The hard part is telling family and guests not to smoke inside.", "plain": "About 603,000 people a year die from others' smoke, 28% of them children. Long-term secondhand exposure runs hypertension, heart disease, and stroke about 30–50% higher — and smoke breathed at home hits harder than smoke elsewhere.", "benefit_text": "Öberg et al. (2011): 603,000 deaths attributable to secondhand smoke in 2004 (~1.0% of global mortality); 28% in children, 61% of DALYs in children. 2026 meta-analysis (57 studies): hypertension OR 1.28, heart disease OR 1.39, myocardial infarction OR 1.50, stroke OR 1.36 (about 30–50% higher) — home exposure riskier than non-home — figures UNVERIFIED in this edition (no citable source found; see docs/verification/spot-read.md).", "sources": "Öberg M et al. (2011). Worldwide burden of disease from exposure to second-hand smoke. Lancet. <https://doi.org/10.1016/S0140-6736(10)61388-8>", "notes": "**Ontario law:** The Smoke-Free Ontario Act s.9.2 bans smoking in a vehicle with anyone under 16 inside; smoking is also banned in enclosed workplaces and public places. Start with the home — people spend the most hours there, and children absorb 61% of secondhand smoke's health damage.", "urls": ["https://doi.org/10.1016/S0140-6736(10"]}, {"id": "02-003", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 3, "title": "Don't quit on willpower alone — get medication first: it more than doubles success", "money": "low", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Nicotine patches and gum are over-the-counter, roughly $30–$60 for an 8–12 week course. Varenicline and bupropion need a prescription. The cost is roughly offset by the cigarettes you don't buy.", "plain": "Willpower alone fails most people. Varenicline users quit at more than double the placebo rate. Nicotine replacement runs about 55% better than no medication, and patch plus a fast-acting form (gum, lozenge) adds another 27%.", "benefit_text": "Cochrane: varenicline vs placebo — RR 2.32 (95% CI 2.15–2.51), high-certainty; vs bupropion RR 1.36; vs single NRT RR 1.25. NRT vs control — RR 1.55 (55% better, 95% CI 1.49–1.61), 133 trials, 64,640 people. Patch + fast-acting form vs single form — RR 1.27 (27% more, 95% CI 1.17–1.37), high-certainty.", "sources": "Livingstone-Banks J et al. (2023). Nicotine receptor partial agonists for smoking cessation. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD006103.pub8>; Hartmann-Boyce J et al. (2018). Nicotine replacement therapy versus control for smoking cessation. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD000146.pub5>", "notes": "**Canada:** NRT is OTC at any pharmacy; varenicline and bupropion need a prescription from your doctor. Varenicline commonly causes nausea and vivid dreams — tell your doctor about any psychiatric history. Pair medication with a quit date (item 4) and counselling (item 5).", "urls": ["https://doi.org/10.1002/14651858.CD000146.pub5", "https://doi.org/10.1002/14651858.CD006103.pub8"]}, {"id": "02-004", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 4, "title": "Set a quit date — stop all at once, don't taper first", "money": "0", "time": "low", "willpower": "yes", "benefit": "mid", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. Pick a day on the calendar and tell family and coworkers ahead of time.", "plain": "Many plan to smoke fewer each day down to zero. At six months, 22.0% of abrupt quitters were still off cigarettes versus 15.5% of gradual reducers. So set a date and stop all at once — and start nicotine replacement two weeks before the date.", "benefit_text": "Lindson-Hawley et al. (2016), 697 UK smokers randomized: abrupt vs gradual — 22.0% vs 15.5% abstinent at 6 months (RR 0.71, 95% CI 0.46–0.91); 49.0% vs 39.2% at 4 weeks. Starting NRT before quit day vs on the day: ~25% higher success (RR 1.25, 95% CI 1.08–1.44, moderate-certainty).", "sources": "Lindson-Hawley N et al. (2016). Gradual Versus Abrupt Smoking Cessation. Annals of Internal Medicine. <https://doi.org/10.7326/M14-2805>", "notes": "Disputed: an older Cochrane review found the two methods similar (RR 0.94), but it was withdrawn in 2019 and is no longer updated — the randomized trial above is the best current evidence. Benefit graded mid: the endpoint is quit rates, not mortality.", "urls": ["https://doi.org/10.7326/M14-2805"]}, {"id": "02-005", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 5, "title": "Use a quit clinic or helpline — medication plus follow-up beats either alone", "money": "low", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "The helpline is free. A clinic visit is OHIP-covered via your family doctor — typically 4–8 sessions of 30–60 minutes.", "plain": "Pills and \"someone checking in on you\" are two different things, and together they work best: medication plus counselling quits at nearly double the rate of brief advice alone. Proactive quitline callbacks add about 38%.", "benefit_text": "Cochrane (Stead 2016; 52 trials, 19,488 people): combined pharmacotherapy + behavioural support vs usual care — RR 1.83 (95% CI 1.68–1.98), high-quality. Telephone counselling (Matkin 2019): multiple proactive callbacks vs materials only — RR 1.38 (38% more, 95% CI 1.19–1.61), moderate-certainty.", "sources": "Stead LF et al. (2016). Combined pharmacotherapy and behavioural interventions for smoking cessation. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD008286.pub3>; Matkin W et al. (2019). Telephone counselling for smoking cessation. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD002850.pub4>", "notes": "**Ontario:** Smokers' Helpline at 1-877-513-5333 — free quit coaches by phone, text, and online. Ask your family doctor or pharmacist for a referral too. Most trials were outside Canada and clinic intensity varies, so read the numbers as direction. Medication: item 3.", "urls": ["https://doi.org/10.1002/14651858.CD002850.pub4", "https://doi.org/10.1002/14651858.CD008286.pub3"]}, {"id": "02-006", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 6, "title": "Consider vaping only if nothing else worked — never-smokers stay away", "money": "low", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Device plus pods, tens of dollars a month. Buy only at licensed retailers.", "plain": "Switching to nicotine vapes beats nicotine patches by about 61% for quitting — roughly 4 extra quitters per 100. But vaping is not harmless, and long-term safety data don't exist yet. If you don't smoke, it offers nothing.", "benefit_text": "Lindson et al. (2026), living review, 80 trials, 29,861 people: nicotine e-cigarettes vs NRT — RR 1.61 (61% better, 95% CI 1.23–2.12), high-certainty, ~4 more quitters per 100 (1–7). Serious adverse events: similar between groups.", "sources": "Lindson N et al. (2026). Electronic cigarettes for smoking cessation. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD010216.pub11>", "notes": "**Canada:** The Tobacco and Vaping Products Act bans sales to minors (19+ in Ontario); provinces restrict flavours and where vapes may be sold — buy only from licensed retailers, never off social media. Disputed: WHO does not recommend vapes for quitting (long-term data gaps, youth uptake); the UK includes them in stop-smoking services. The trials used regulated nicotine products — mystery oils are a different, untested thing. Try item 3's medications first: harder evidence, cheaper.", "urls": ["https://doi.org/10.1002/14651858.CD010216.pub11"]}, {"id": "02-007", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 7, "title": "Don't drink sugary drinks — switching to diet doesn't fix it", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free — and water or unsweetened tea saves money. The hard part is breaking the sweet-drink habit, diet versions included.", "plain": "Two-plus sugary drinks a day runs about 21% higher death; one to two a day, about 14% higher. Diet drinks show no benefit: two-plus cups a day ran about 26% higher.", "benefit_text": "Malik et al. (2019), ~118,000 US adults: ≥2 servings/day HR 1.21 (21% higher), 1–2/day HR 1.14 (14% higher) vs <1/month. EPIC (450,000 people, 10 countries): sugary ≥2 glasses/day HR 1.08 (95% CI 1.01–1.16); artificially sweetened HR 1.26 (26% higher, 1.16–1.35); all soft drinks HR 1.17 (1.11–1.22).", "sources": "Malik VS et al. (2019). Long-Term Consumption of Sugar-Sweetened and Artificially Sweetened Beverages and Risk of Mortality in US Adults. Circulation. <https://doi.org/10.1161/CIRCULATIONAHA.118.037401>; Mullee A et al. (2019). Association Between Soft Drink Consumption and Mortality in 10 European Countries. JAMA Internal Medicine. <https://doi.org/10.1001/jamainternmed.2019.2478>", "notes": "Disputed on diet drinks: the stronger link for sweeteners is likely reverse causation — overweight and diabetic people switch to diet. Don't read it as \"sweeteners are more toxic\" — but \"diet is fine\" has no evidence behind it either. Water or unsweetened tea is the safe switch.", "urls": ["https://doi.org/10.1001/jamainternmed.2019.2478", "https://doi.org/10.1161/CIRCULATIONAHA.118.037401"]}, {"id": "02-008", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 8, "title": "Don't chew betel nut", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free — and it saves the money you'd spend on it. The hard part is breaking the chewing habit.", "plain": "Chewers run about 21% higher death, about 47% more diabetes, and about 51% more metabolic syndrome than non-chewers. Oral and oesophageal cancer sit on top of that.", "benefit_text": "Yamada et al. (2013), meta-analysis of 17 Asian studies, 388,000 people: all-cause mortality RR 1.21 (21% higher, P=0.02); diabetes RR 1.47 (47% higher); metabolic syndrome RR 1.51 (51% higher). Betel nut is a known cause of oral and oesophageal cancer.", "sources": "Yamada T, Hara K, Kadowaki T (2013). Chewing betel quid and the risk of metabolic disease, cardiovascular disease, and all-cause mortality. PLoS One. <https://doi.org/10.1371/journal.pone.0070679>", "notes": "**Canada:** Betel nut isn't a regulated product here, but it's sold in some South and Southeast Asian grocery stores — the evidence travels with the habit. Longer years and more per day raise oral-cancer risk further; risk falls after quitting. Tobacco-containing quids are worse.", "urls": ["https://doi.org/10.1371/journal.pone.0070679"]}, {"id": "02-009", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 9, "title": "Swap table salt for low-sodium (potassium) salt", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "A bag costs a few dollars more. Grab it on a normal shop — no extra time, nearly no taste difference.", "plain": "In stroke survivors and hypertensives over 60, switching to low-sodium salt meant about 12% lower death and 14% fewer strokes over five years.", "benefit_text": "Neal et al. (2021), randomized trial, 20,995 rural Chinese adults (prior stroke or 60+ with hypertension), 4.74 years: low-sodium salt vs regular — death RR 0.88 (12% lower), stroke RR 0.86 (14% lower), major cardiovascular events RR 0.87. No significant difference in high-potassium events.", "sources": "Neal B et al. (2021). Effect of Salt Substitution on Cardiovascular Events and Death. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa2105675>", "notes": "Disputed: the PURE observational study found both very low (<3 g/day urinary sodium) and very high (>7 g/day) excretion linked to higher risk — but the trial's substitution doesn't push sodium that low. The trial population was high-risk older adults; healthy young people gain far less. Kidney disease or potassium-sparing drugs: ask your doctor first.", "urls": ["https://doi.org/10.1056/NEJMoa2105675"]}, {"id": "02-010", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 10, "title": "Brush well, clean between teeth daily, replace missing teeth", "money": "low", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Floss or interdental brushes run about $10–$20 a year; a cleaning $100–$300. Two to three extra minutes a day. The hard part is making it daily.", "plain": "Daily interdental cleaning runs about 11% lower death. Older adults with no teeth run about 87% higher death; under 20 teeth, about double.", "benefit_text": "Wang et al. (2026), 9,676 Japanese adults, 6 years: interdental cleaning HR 0.89 (11% lower). Ko et al. (2026), meta-analysis of community-dwelling older adults: edentulous vs dentate OR 1.87 (87% higher, 95% CI 1.35–2.59); <20 teeth OR 2.04 (1.67–2.49).", "sources": "Wang K et al. (2026). Routine oral health practices and all-cause mortality. Journal of Dentistry. <https://doi.org/10.1016/j.jdent.2026.106789>; Ko MJ et al. (2026). Deteriorated oral health and function as risk factors for physical disability and mortality in community-dwelling older adults. European Geriatric Medicine. <https://doi.org/10.1007/s41999-025-01319-4>", "notes": "**Canada:** Dental care is mostly private, but the Canadian Dental Care Plan covers eligible residents — check eligibility. Disputed: these are follow-up studies — people with bad teeth are often sicker and poorer overall, so tooth vs body causation is unclear. Either way the cost is trivial, and gum disease and missing teeth already hurt eating.", "urls": ["https://doi.org/10.1007/s41999-025-01319-4", "https://doi.org/10.1016/j.jdent.2026.106789"]}, {"id": "02-011", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 11, "title": "Walk 7,000–8,000 steps a day", "money": "0", "time": "high", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. Sixty to ninety minutes a day, splittable into commutes and errands. The hard part is doing it daily.", "plain": "People walking 5,800 steps a day run about 40% lower death than those at 3,500; at 7,800 steps, about 45% lower. Past a point the curve flattens — 6,000–8,000 is enough at 60+.", "benefit_text": "Paluch et al. (2022), meta-analysis of 15 cohorts, 47,471 people, 3,013 deaths: vs lowest quartile (median 3,553 steps/day, about 3,500) — 5,801 steps (about 5,800) HR 0.60 (40% lower), 7,842 steps (about 7,800) HR 0.55 (45% lower), 10,901 steps HR 0.47. Plateau at 6,000–8,000 steps for 60+, 8,000–10,000 under 60.", "sources": "Paluch AE et al. (2022). Daily steps and all-cause mortality: a meta-analysis of 15 international cohorts. Lancet Public Health. <https://doi.org/10.1016/S2468-2667(21)00302-9>", "notes": "The 4,000→7,000 stretch is the best value — no need to force 10,000. These are follow-up studies: the least-walking group includes people already too sick to walk, so the gaps read too large — but the more-is-better trend is clear. Same thing as item 14 in different units; hit one of them.", "urls": ["https://doi.org/10.1016/S2468-2667(21"]}, {"id": "02-012", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 12, "title": "High blood pressure or cholesterol: take the pills on schedule, don't stop on your own", "money": "low", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Generic blood-pressure pills and statins cost a few dollars a month with coverage. Once a day, seconds. The hard part is never stopping.", "plain": "Every 10 mmHg lower blood pressure means about 13% lower death and 27% fewer strokes. Statins: each 1.0 mmol/L lower LDL means about 10% lower death. People taking ≥80% of doses run 29–45% lower death than frequent skippers.", "benefit_text": "Randomized-trial meta-analyses: per 10 mmHg lower systolic — death RR 0.87 (13% lower), major cardiovascular events RR 0.80, stroke RR 0.73 (27% fewer), heart failure RR 0.72 (Ettehad 2016). Per 1.0 mmol/L lower LDL — death RR 0.90 (10% lower), major vascular events RR 0.78 (CTT 2010). Adherence meta-analysis: ≥80% adherent vs not — statins RR 0.55 (45% lower), antihypertensives RR 0.71 (29% lower) (Chowdhury 2013).", "sources": "Ettehad D et al. (2016). Blood pressure lowering for prevention of cardiovascular disease and death. Lancet. <https://doi.org/10.1016/S0140-6736(15)01225-8>; Cholesterol Treatment Trialists' Collaboration (2010). Efficacy and safety of more intensive lowering of LDL cholesterol. Lancet. <https://doi.org/10.1016/S0140-6736(10)61350-5>", "notes": "Only if your doctor says you need them — healthy people don't take these. The adherence numbers are observational (adherent people are more disciplined generally, inflating the benefit); the trial numbers above are the reliable ones. No separate blood-sugar item here: tighter glucose control doesn't cut total mortality as consistently as blood pressure and lipids do.", "urls": ["https://doi.org/10.1016/S0140-6736(10", "https://doi.org/10.1016/S0140-6736(15"]}, {"id": "02-013", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 13, "title": "Sleep about 7 hours a night, on a fixed schedule", "money": "0", "time": "high", "willpower": "some", "benefit": "mid", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. You pay in time — mostly traded from phone-scrolling. The hard part is fixing bedtime and wake time.", "plain": "Habitual short sleepers run about 12% higher death. But regularity matters more than duration: the most regular sleepers run 20–48% lower death than the most irregular. Weekend-vs-weekday sleep midpoints differing by 2+ hours mean about 30% more heart disease.", "benefit_text": "Meta-analyses: short sleep RR 1.12 (12% higher), long sleep RR 1.30 (Cappuccio 2010); per hour under 7, RR 1.06; per hour over 7, RR 1.13 (Yin 2017). UK Biobank wristwatch data (~61,000 people): the four more-regular groups ran 20%–48% lower death than the most irregular (Windred 2024). Social jet lag ≥2 h (2+ hours): HR 1.30 (30% more, 95% CI 1.11–1.54) for cardiovascular disease (Kumar 2026).", "sources": "Cappuccio FP et al. (2010). Sleep duration and all-cause mortality. Sleep. <https://doi.org/10.1093/sleep/33.5.585>; Windred DP et al. (2024). Sleep regularity is a stronger predictor of mortality risk than sleep duration. Sleep. <https://doi.org/10.1093/sleep/zsad253>", "notes": "Fix short sleep and irregular schedules — don't compress sleep on purpose. Long sleepers' higher risk is mostly reverse causation (depression, chronic disease, sleep apnea make people sleep more). Regularity's evidence is two follow-up studies (B-grade alone). Catching up after a bad night: item 39.", "urls": ["https://doi.org/10.1093/sleep/33.5.585", "https://doi.org/10.1093/sleep/zsad253"]}, {"id": "02-014", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 14, "title": "150–300 minutes a week of moderate exercise — brisk walking counts", "money": "0", "time": "high", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Free. Twenty to forty-five minutes a day. The hard part is years of it.", "plain": "People hitting 150–300 brisk-walking minutes a week run about 31% lower death than non-exercisers. Even below the guideline: about 20% lower. Three to five times the guideline maxes out around 39% — more adds nothing further, but no harm either.", "benefit_text": "Arem et al. (2015), pooled dose-response: 1–2× guideline (7.5–15 MET-h/week ≈ 150–300 brisk minutes) HR 0.69 (31% lower); below guideline HR 0.80 (20% lower); 3–5× HR 0.61 (39% lower, the floor); 10×+ HR 0.69. Accelerometer meta-analysis (Ekelund 2019): most vs least active quarter HR 0.52.", "sources": "Arem H et al. (2015). Leisure time physical activity and mortality. JAMA Internal Medicine. <https://doi.org/10.1001/jamainternmed.2015.0533>; Ekelund U et al. (2019). Dose-response associations between accelerometry measured physical activity and sedentary time and all cause mortality. BMJ. <https://doi.org/10.1136/bmj.l4570>", "notes": "Pick this or item 11 — they measure the same thing. These are follow-up studies; the accelerometer ones tracked older people briefly, mixing in \"already sick, so inactive.\" The true benefit is smaller than HR 0.52 suggests.", "urls": ["https://doi.org/10.1001/jamainternmed.2015.0533", "https://doi.org/10.1136/bmj.l4570"]}, {"id": "02-015", "chapter_num": 2, "chapter_title": "Don't Die Slowly", "chapter_file": "02-dont-die-slowly.md", "number": 15, "title": "Racket sports three times a week, 45 minutes each", "money": "low", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Court fees roughly $10–$30 a session. About 2 hours a week. The hard part is rounding up people and courts, weekly.", "plain": "Regular tennis, badminton, table-tennis players run about 47% lower death and 56% lower cardiovascular death than non-players. Swimmers run about 28% lower. Running and soccer showed no difference in this dataset.", "benefit_text": "Oja et al. (2017), 80,306 UK adults: racket sports vs none — all-cause HR 0.53 (47% lower, 95% CI 0.40–0.69), cardiovascular death HR 0.44 (56% lower, 0.24–0.83). Swimming 0.72/0.59 (28% lower); aerobics 0.73/0.64; cycling 0.85. Running and football: no significant difference.", "sources": "Oja P et al. (2017). Associations of specific types of sports and exercise with all-cause and cardiovascular-disease mortality. British Journal of Sports Medicine. <https://doi.org/10.1136/bjsports-2016-096822>", "notes": "Disputed: follow-up data only — racket players were healthier and more social to begin with, and runners showing nothing suggests the picker matters more than the sport. Don't conclude running is useless; total-volume items are 11 and 14.", "urls": ["https://doi.org/10.1136/bjsports-2016-096822"]}]);
